const API='/api/v1/miniapp';const tg=window.Telegram?.WebApp;const app=document.getElementById('app');const S={page:'home',session:null,data:null,busy:false};
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function badge(v){const s=String(v??'—').toUpperCase();const c=s.includes('ACTIVE')||s.includes('OPEN')||s==='TRUE'?'ok':s.includes('LOCK')||s.includes('OFF')||s==='FALSE'?'bad':'';return `<span class="badge ${c}">${esc(s)}</span>`}
function toast(t){const d=document.createElement('div');d.className='toast';d.textContent=t;document.body.appendChild(d);setTimeout(()=>d.remove(),2400)}
async function api(path,opt={}){const h=new Headers(opt.headers||{});h.set('Content-Type','application/json');if(tg?.initData)h.set('X-Telegram-Init-Data',tg.initData);const r=await fetch(API+path,{...opt,headers:h});let d=null;try{d=await r.json()}catch{}if(!r.ok)throw new Error(d?.detail||('HTTP '+r.status));return d}
function openTelegram(url){if(!url)return;tg?.openTelegramLink?tg.openTelegramLink(url):window.open(url,'_blank')}
function nav(){return `<nav class="nav">${[['home','خانه'],['signals','سیگنال'],['trade','اتو ترید'],['plans','اشتراک'],['support','پشتیبانی']].map(([p,l])=>`<button data-nav="${p}" class="${S.page===p?'active':''}">${l}</button>`).join('')}</nav>`}
function head(){return `<div class="head"><div class="brand"><div class="logo">N</div><div><small>NEXUS</small><h1>${esc(S.session?.user?.first_name||'کاربر')}</h1></div></div><button id="refresh">↻</button></div>`}
function shell(body){app.innerHTML=`<div class="app">${head()}${S.busy?'<div class="loading"></div>':''}${body}${nav()}</div>`;document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav));const r=document.getElementById('refresh');if(r)r.onclick=()=>go(S.page)}
function gate(msg='این مینی‌اپ را از داخل ربات NEXUS باز کنید.'){app.innerHTML=`<main class="gate"><div><div class="logo">N</div><h1>NEXUS</h1><p class="muted">${esc(msg)}</p><button id="retry" class="primary">تلاش دوباره</button></div></main>`;document.getElementById('retry').onclick=boot}
async function boot(){try{tg?.ready();tg?.expand();S.session=await api('/session');await go('home')}catch(e){gate(e.message)}}
async function go(page){S.page=page;S.busy=true;try{if(page==='home'){S.session=await api('/session');S.data=null}else if(page==='signals')S.data=await api('/signals');else if(page==='trade')S.data=await api('/autotrade');else if(page==='plans')S.data=await api('/commerce');else if(page==='support')S.data=await api('/support');render()}catch(e){toast(e.message)}finally{S.busy=false;render()}}
function home(){const s=S.session;return `<section class="card hero"><small>به NEXUS خوش آمدید</small><h2>مرکز دسترسی شما</h2><p class="muted">سیگنال‌ها، اشتراک و خدمات NEXUS را از یک پنل مدیریت کنید.</p></section><button id="public" class="channel public"><span class="ico">◉</span><span><b>ورود به NEXUS</b><small>کانال رسمی و محتوای عمومی</small></span><span>←</span></button><button id="vip" class="channel vip"><span class="ico">◆</span><span><b>کانال سیگنال VIP</b><small>${s.entitlements.vip?'دسترسی شما فعال است':'نیازمند اشتراک VIP'}</small></span><span>${s.entitlements.vip?'🔓':'🔒'}</span></button><div class="grid2"><button class="quick" data-go="signals"><b>سیگنال‌های امروز</b><span>FREE و VIP بر اساس دسترسی</span></button><button class="quick" data-go="plans"><b>خرید اشتراک</b><span>VIP / AutoTrade / Bundle</span></button></div>${s.user.is_admin?'<section class="card"><div class="row"><span>دسترسی ادمین</span><button id="adminOverview">مشاهده وضعیت</button></div><div id="adminBox"></div></section>':''}`}
function signals(){const d=S.data;return `<div class="title"><div><h2>سیگنال‌ها و معاملات امروز</h2><small class="muted">${esc(d.timezone||'Asia/Tehran')}</small></div><span>${d.items.length} مورد</span></div>${d.items.length?d.items.map(x=>x.locked?`<section class="card locked"><div class="signalHead"><div><b>${esc(x.symbol)}</b><small>سیگنال اختصاصی VIP</small></div>${badge(x.status)}</div><div class="lockbox"><div style="font-size:30px">🔒</div><b>جزئیات این سیگنال قفل است</b><p class="muted">برای مشاهده Entry، SL و TPها اشتراک VIP تهیه کنید.</p><button class="primary" data-go="plans">خرید اشتراک VIP</button></div></section>`:`<section class="card"><div class="signalHead"><div><b>${esc(x.symbol)} · ${esc(x.direction)}</b><small>${esc(x.code)} · ${esc(x.timeframe)} · ${esc(x.channel)}</small></div>${badge(x.status)}</div><div class="priceGrid"><div><span>ورود</span><b>${esc(x.entry_price)}</b></div><div><span>حد ضرر</span><b>${esc(x.stop_loss)}</b></div><div><span>نوع سفارش</span><b>${esc(x.order_type)}</b></div></div><div class="targets">${(x.targets||[]).map(t=>`<span>TP${esc(t.target_no)} <b>${esc(t.price)}</b></span>`).join('')}</div></section>`).join(''):'<section class="card"><p class="muted">امروز سیگنالی ثبت نشده است.</p></section>'}`}
function trade(){const d=S.data,r=d.risk;return `<div class="title"><h2>AutoTrade</h2>${badge(d.account?'CONNECTED':'OFFLINE')}</div><section class="card"><h3>مدیریت ریسک</h3><div class="rows"><div class="row"><span>حد زیان روزانه</span><b>${esc(r.daily_loss_limit_r)}R</b></div><div class="row"><span>Dynamic Risk</span>${badge(!!r.dynamic_risk_enabled)}</div><div class="row"><span>حد Loss Streak</span><b>${esc(r.max_loss_streak)}</b></div><div class="row"><span>Kill Switch کاربر</span>${badge(!!r.kill_switch)}</div><div class="row"><span>Kill Switch سراسری</span>${badge(!!d.global_kill_switch)}</div></div><button id="userKill" class="${r.kill_switch?'danger':'primary'}">${r.kill_switch?'فعال‌سازی معاملات جدید':'توقف معاملات جدید'}</button></section><section class="card"><h3>معاملات باز</h3>${d.open.length?d.open.map(x=>`<div class="row"><div><b>${esc(x.symbol||x.signal_code||'NEXUS')}</b><small class="muted">${esc(x.ticket||'')}</small></div>${badge(x.status)}</div>`).join(''):'<p class="muted">معامله بازی وجود ندارد.</p>'}</section>`}
function plans(){const d=S.data;return `<div class="title"><h2>اشتراک‌ها</h2></div>${d.plans.map(p=>`<section class="card"><div class="row"><div><b>${esc(p.fa||p.en||p.code)}</b><small class="muted">${esc(p.days)} روز · ${esc(p.category)}</small></div><div><b>${esc(p.price_usdt)} USDT</b></div></div></section>`).join('')}<section class="card"><h3>اطلاعات پرداخت</h3><div class="rows"><div class="row"><span>کارت</span><b>${esc(d.payment.card||'—')}</b></div><div class="row"><span>نام صاحب کارت</span><b>${esc(d.payment.owner||'—')}</b></div><div class="row"><span>USDT</span><b>${esc(d.payment.usdt_wallet||'—')}</b></div><div class="row"><span>Network</span><b>${esc(d.payment.usdt_network||'—')}</b></div></div><p class="muted">ثبت و تأیید پرداخت از فلو رسمی NEXUS انجام می‌شود.</p></section>`}
function support(){const d=S.data;return `<div class="title"><h2>پشتیبانی</h2></div><section class="card"><label>موضوع<input id="sub"></label><label>پیام<textarea id="msg" rows="4"></textarea></label><button id="sendSupport" class="primary">ارسال درخواست</button></section>${d.items.map(x=>`<section class="card"><div class="signalHead"><b>${esc(x.subject)}</b>${badge(x.status)}</div><p>${esc(x.message)}</p>${x.admin_reply?`<div class="card" style="margin:8px 0 0"><b>پاسخ پشتیبانی</b><p>${esc(x.admin_reply)}</p></div>`:''}</section>`).join('')}`}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));if(S.page==='home'){document.getElementById('public').onclick=()=>openTelegram(S.session.links.public);document.getElementById('vip').onclick=async()=>{if(!S.session.entitlements.vip)return go('plans');try{const x=await api('/vip-channel-link',{method:'POST'});openTelegram(x.url)}catch(e){toast(e.message)}};const a=document.getElementById('adminOverview');if(a)a.onclick=async()=>{try{const x=await api('/admin/overview');document.getElementById('adminBox').innerHTML=`<div class="rows"><div class="row"><span>کاربران</span><b>${esc(x.stats.users)}</b></div><div class="row"><span>اشتراک فعال</span><b>${esc(x.stats.active)}</b></div><div class="row"><span>Kill Switch</span>${badge(x.global_kill_switch)}</div><div class="row"><span>Signal issuance در Mini App</span>${badge(x.signal_issue)}</div></div>`}catch(e){toast(e.message)}}}if(S.page==='trade'){const b=document.getElementById('userKill');if(b)b.onclick=async()=>{const r=S.data.risk;try{await api('/risk',{method:'PUT',body:JSON.stringify({kill_switch:!r.kill_switch})});toast('تنظیمات ذخیره شد');go('trade')}catch(e){toast(e.message)}}}if(S.page==='support'){const b=document.getElementById('sendSupport');if(b)b.onclick=async()=>{const subject=document.getElementById('sub').value.trim(),message=document.getElementById('msg').value.trim();if(subject.length<2||message.length<2)return toast('موضوع و پیام را کامل کنید');try{await api('/support',{method:'POST',body:JSON.stringify({subject,message,priority:'NORMAL'})});toast('درخواست ثبت شد');go('support')}catch(e){toast(e.message)}}}}
function render(){if(!S.session)return gate();let body=S.page==='home'?home():S.page==='signals'?signals():S.page==='trade'?trade():S.page==='plans'?plans():support();shell(body);bind()}
boot();
